CREATE TABLE principal(id BINARY(16) PRIMARY KEY,principal_type VARCHAR(24) NOT NULL,external_owner_id BINARY(16) NOT NULL,login_name VARCHAR(190) NOT NULL,password_hash VARCHAR(255) NOT NULL,status VARCHAR(24) NOT NULL,failed_login_count INT NOT NULL DEFAULT 0,locked_until TIMESTAMP(6) NULL,password_changed_at TIMESTAMP(6) NOT NULL,version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_principal_login UNIQUE(login_name),INDEX ix_principal_owner(external_owner_id));
CREATE TABLE principal_role(principal_id BINARY(16) NOT NULL,role_code VARCHAR(64) NOT NULL,created_at TIMESTAMP(6) NOT NULL,PRIMARY KEY(principal_id,role_code),CONSTRAINT fk_role_principal FOREIGN KEY(principal_id) REFERENCES principal(id));
CREATE TABLE refresh_token(id BINARY(16) PRIMARY KEY,principal_id BINARY(16) NOT NULL,family_id BINARY(16) NOT NULL,token_hash BINARY(32) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,used_at TIMESTAMP(6) NULL,revoked_at TIMESTAMP(6) NULL,replaced_by_id BINARY(16) NULL,created_at TIMESTAMP(6) NOT NULL,CONSTRAINT uk_refresh_hash UNIQUE(token_hash),INDEX ix_refresh_principal_expiry(principal_id,expires_at),INDEX ix_refresh_family(family_id),CONSTRAINT fk_refresh_principal FOREIGN KEY(principal_id) REFERENCES principal(id));

